// World Health & Disparities Practice Test 1. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items: defining equity, measuring gaps and judging
// interventions. Content follows the Valus World Health & Disparities lessons and their sources.
import {q, mix} from './q.js';
const BARR='Barr, Health Disparities in the United States', WHO='WHO, Health Equity', NIMHD='National Institute on Minority Health and Health Disparities', KFF='KFF', OWID='Our World in Data';
const WH='What is Health', HD='Health Disparities & Diversity', TR='Disparities in Treatment & Medical Decisions', RED='Reducing Health Disparities';

export default {
 id:'world-health-disparities-1',
 event:'World Health & Disparities',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Barr’s Health Disparities in the United States, WHO health equity materials, NIMHD, KFF and Our World in Data',
 plan:[{area:WH,weight:20},{area:HD,weight:40},{area:TR,weight:20},{area:RED,weight:20}],
 questions:mix([
  q(WH,'How does the WHO define health equity?','No unfair, avoidable health differences',['Giving every person identical medical care','Equal health outcomes for every individual','Free health care in every country'],'B','Health inequities are differences that are unfair and avoidable, whether groups are defined socially, economically, demographically or geographically.',WHO),
  q(WH,'How does equity differ from equality?','Equity gives people what they need',['Equity gives everyone the same resources','Equity and equality mean the same thing','Equity applies only to income levels'],'D','Equality distributes resources equally; equity adjusts resources to need so that everyone has a fair chance at health.',WHO),
  q(WH,'Which model, proposed by George Engel in 1977, adds psychological and social factors to biology in understanding illness?','Biopsychosocial model',['Biomedical model','Germ theory','Social gradient model'],'A','The biomedical model focuses on disease and biology; the biopsychosocial model recognizes stress, relationships and beliefs as influences on health.',BARR),
  q(WH,'What are the social determinants of health?','The conditions where people live, work and age',['Only a person’s inherited genes','The number of hospitals in a country','Only the medicines a person takes daily'],'C','Healthy People groups them into economic stability, education, health care access, neighborhood and built environment, and social and community context.',WHO),
  q(WH,'How is the infant mortality rate defined?','Deaths of infants under 1 year per 1,000 live births',['Deaths of children under 5 per 100,000 births','Deaths during childbirth per 100 mothers','Deaths of newborns in the first hour'],'B','The maternal mortality ratio, by contrast, is maternal deaths per 100,000 live births.',OWID),
  q(WH,'What does a disability-adjusted life year (DALY) measure?','Healthy years lost to death and disability',['Total years of education completed','The number of hospital beds per person','A country’s spending on health'],'D','DALYs let researchers compare the total burden of very different diseases.',OWID),
  q(WH,'Group A has an infant mortality rate of 20 per 1,000, and Group B has 10 per 1,000. What are the rate difference and the rate ratio?','10 per 1,000 and 2',['2 per 1,000 and 10','30 per 1,000 and 0.5','10 per 1,000 and 0.5'],'A','The difference (20 − 10) shows the absolute gap; the ratio (20 ÷ 10) shows the relative gap.',BARR),
  q(WH,'As countries develop, deaths shift from infectious diseases toward chronic noncommunicable diseases. What is this pattern called?','The epidemiological transition',['The demographic dividend','The social gradient in health','The Hispanic health paradox'],'C','Life expectancy rises as infectious, maternal and nutritional causes decline and chronic diseases become leading causes of death.',OWID),
  q(WH,'Which intervention is considered “upstream”?','Changing housing policy to improve living conditions',['Prescribing medication for high blood pressure','Performing coronary bypass surgery','Treating a hospitalized patient’s infection'],'B','Upstream efforts change the conditions that cause disease; downstream efforts treat disease after it appears.',BARR),
  q(WH,'Which statement describes the social gradient in health?','Health improves at each step up the ladder',['Only the very poorest have worse health','Health is unrelated to income','Wealth always guarantees perfect health'],'D','The gradient shows that disparities affect everyone along the socioeconomic scale, not just the poorest.',BARR),
  q(HD,'According to NIMHD, what makes a health difference a health disparity?','It is linked to social disadvantage',['It is caused only by genetics','It affects only one person at a time','It disappears without any intervention'],'A','Disparities affect groups who have systematically experienced greater obstacles to health.',NIMHD),
  q(HD,'What does socioeconomic status (SES) combine?','Income, education and occupation',['Age, sex and adult height','Blood type, weight and diet','Religion, hobbies and sports'],'C','SES is strongly linked to health outcomes across many conditions.',BARR),
  q(HD,'Which term describes how policies and institutions such as housing, schools and health care produce unequal outcomes by race, even without individual intent?','Structural racism',['Implicit bias only','Acculturation','Health literacy'],'B','Historic policies such as redlining still shape neighborhoods, pollution exposure and access to resources.',BARR),
  q(HD,'What was redlining?','Denying mortgages in Black neighborhoods',['Marking hospital beds for emergencies','A method of triage in disasters','A local tax on unhealthy foods'],'D','Redlining shaped residential segregation that continues to influence schools, environment and health.',BARR),
  q(HD,'Which hypothesis proposes that chronic stress from discrimination accelerates biological aging?','The weathering hypothesis',['The hygiene hypothesis','The thrifty gene hypothesis','The germ hypothesis'],'A','Weathering may help explain why some disparities grow larger with age.',BARR),
  q(HD,'Why do researchers call for disaggregated data?','Broad categories can hide large differences among subgroups',['Combined data are always more accurate','Disaggregation reduces sample sizes for no reason','It removes the need for any surveys'],'C','Outcomes differ greatly among Asian American subgroups and among Hispanic subgroups, for example.',NIMHD),
  q(HD,'What is the “Hispanic health paradox”?','Better outcomes than SES would predict',['Hispanic Americans have the lowest life expectancy','Hispanic data are never collected','Hispanic patients never face barriers to care'],'B','Researchers still debate the causes, which may include social support, migration patterns and data issues.',BARR),
  q(HD,'Who introduced the term intersectionality?','Kimberlé Crenshaw',['George Engel','Rudolf Virchow','Paul Farmer'],'D','Intersectionality describes how overlapping identities, such as race, gender and disability, create distinct experiences of advantage and disadvantage.',BARR),
  q(HD,'The minority stress model explains health disparities among which group especially?','Sexual and gender minorities',['Professional athletes in contact sports','Hospital administrators','High-income retirees'],'A','Chronic stress from stigma, discrimination and concealment can affect mental and physical health.',NIMHD),
  q(HD,'Why are people with limited English proficiency at risk for poorer care?','Miscommunication can cause errors',['They never need medical care','Interpreters are always required to be family members','They receive care only in emergency rooms'],'C','Qualified medical interpreters reduce errors and improve satisfaction.',NIMHD),
  q(HD,'Which group faces a sharply higher risk of overdose death shortly after a life change?','People recently released from prison',['People starting a new job','Students graduating high school','People moving to a new city for work'],'B','Lost tolerance, interrupted treatment and lack of support after release raise overdose risk.',NIMHD),
  q(HD,'What is “underinsurance”?','Coverage that leaves care unaffordable',['Having no insurance at all','Having two insurance plans','Having insurance only for dental care'],'D','High deductibles and limited benefits can leave insured people unable to afford needed care.',KFF),
  q(HD,'What does health literacy mean?','Finding, understanding and using health information',['The number of years of school completed','The ability to read medical journals','Knowing the names of all common diseases'],'A','Limited health literacy occurs at every education level and is linked to poorer outcomes.',NIMHD),
  q(HD,'Many low- and middle-income countries face a “double burden.” What is it?','Infectious and chronic disease together',['Two separate health ministries','Two kinds of health insurance','A shortage of both doctors and hospitals only'],'C','Health systems must address malaria, TB and malnutrition while diabetes and heart disease increase.',WHO),
  q(HD,'Low height for age in children, often from chronic undernutrition, is called:','Stunting',['Wasting','Obesity','Rickets'],'B','Stunting affects physical and cognitive development and is a key global child health indicator.',WHO),
  q(HD,'Why is climate change considered a health equity issue?','Its harms fall hardest on the poorest',['It affects every person exactly equally','It only affects wealthy countries','It has no proven link to health'],'D','Heat, floods and food insecurity disproportionately affect low-income communities and countries.',WHO),
  q(HD,'People experiencing homelessness have higher rates of chronic disease partly because they:','Struggle to store medicine and keep visits',['Choose not to use any care','Never have chronic diseases diagnosed','Live longer than the general population'],'A','Unstable housing makes managing chronic conditions and following treatment plans very hard.',NIMHD),
  q(HD,'NIMHD’s research framework includes five domains of influence. Which is one of them?','Physical/built environment',['Political party affiliation','Media consumption habits','Stock market trends'],'C','The domains are biological, behavioral, physical/built environment, sociocultural environment and health care system.',NIMHD),
  q(HD,'In the NIMHD framework, which are the four levels of influence?','Individual, interpersonal, community and societal',['Local, state, national and global only','Child, teen, adult and elder','Primary, secondary, tertiary and quaternary care'],'B','Disparities arise from interactions across domains and levels.',NIMHD),
  q(HD,'Health care for members of federally recognized American Indian and Alaska Native tribes is provided by which agency?','Indian Health Service',['Veterans Health Administration','National Health Service Corps','Medicare'],'D','Underfunding and distance to facilities contribute to disparities in Native communities.',KFF),
  q(TR,'What is implicit bias?','Automatic associations that operate without awareness',['Openly stated, conscious prejudice','A legal requirement to treat everyone equally','A type of statistical error'],'A','Implicit bias can conflict with a person’s stated values and affect clinical decisions.',BARR),
  q(TR,'Why was race removed from the commonly used eGFR kidney function equation?','It overestimated Black patients’ kidney function',['It made the test far too expensive','It was too difficult to calculate by hand','It was never used in practice'],'C','Removing the race coefficient helps patients be referred for specialist care and transplant lists sooner.',NIMHD),
  q(TR,'Why can pulse oximeters contribute to disparities?','They may read falsely high on darker skin',['They cannot be used on young children','They work only in hospital settings','They measure blood sugar incorrectly'],'B','Overestimation can delay recognition of hypoxemia and treatment.',NIMHD),
  q(TR,'An algorithm predicts health needs using past health spending. Why might it disadvantage some groups?','Low access lowered spending, hiding need',['Algorithms cannot process cost data','Spending always equals true need','Algorithms ignore all data'],'D','Using a biased proxy reproduces existing inequities in access.',BARR),
  q(TR,'What does shared decision-making involve?','Clinician and patient deciding together',['The clinician deciding alone quickly','The patient deciding without information','The insurer making the final choice'],'A','It respects patient preferences and can improve satisfaction and adherence.',BARR),
  q(TR,'What has patient-clinician concordance (such as shared race or language) been associated with in some studies?','Better communication and satisfaction',['Lower-quality care','Higher medication costs','Longer wait times for all patients'],'C','This is one reason efforts to diversify the health workforce are encouraged.',BARR),
  q(TR,'Which federal standards give health organizations a blueprint for culturally and linguistically appropriate services?','The National CLAS Standards',['The HIPAA Security Rule','The EMTALA statute','The Stark self-referral law'],'B','The CLAS Standards were published by the HHS Office of Minority Health.',NIMHD),
  q(TR,'Attributing a patient’s new symptoms to an existing disability, delaying diagnosis, is called:','Diagnostic overshadowing',['Shared decision-making','Teach-back','Patient navigation'],'D','People with disabilities and mental illness are especially affected.',NIMHD),
  q(TR,'Which communication technique checks understanding by asking patients to explain instructions in their own words?','Teach-back',['Closed questioning','Jargon reduction only','Rapid discharge'],'A','Teach-back reveals misunderstandings so the clinician can explain again.',NIMHD),
  q(TR,'Why is collecting sexual orientation and gender identity (SOGI) data voluntarily and confidentially important?','So disparities can be measured',['To deny insurance coverage','To report patients to employers','To replace clinical exams'],'C','Inclusive forms, correct names and pronouns, and clinician training also support equitable care.',NIMHD),
  q(RED,'Who are community health workers?','Trusted local care navigators',['Hospital-based surgeons','Insurance claims processors','Federal health regulators'],'B','CHWs provide health education and connect families to services, improving access in underserved communities.',NIMHD),
  q(RED,'What does the “Health in All Policies” approach ask?','Every sector considers how its decisions affect health',['Only health departments make health decisions','Hospitals set transportation policy','Schools stop teaching health classes'],'D','Housing, transportation, education and labor policies all shape health.',WHO),
  q(RED,'Which program expansion under the Affordable Care Act most increased coverage for low-income adults in participating states?','Medicaid expansion',['Medicare Part D','The Indian Health Service','Veterans benefits'],'A','States that expanded Medicaid saw larger drops in uninsured rates.',KFF),
  q(RED,'Federally supported health centers help reduce disparities mainly by:','Primary care regardless of ability to pay',['Offering only elective cosmetic surgery','Serving only insured patients','Replacing emergency departments'],'C','Health centers are supported by HRSA and use sliding-fee scales.',KFF),
  q(RED,'Why do administrative burdens reduce the effectiveness of programs such as Medicaid?','Paperwork makes eligible people lose coverage',['They make coverage free for everyone','They increase the number of doctors','They remove all eligibility rules'],'B','Frequent renewals and documentation requirements led many eligible people to lose coverage after the pandemic.',KFF),
  q(RED,'What is a culturally tailored intervention?','A program adapted to a community’s culture',['A program that is the same for everyone','A program run only inside hospitals','A program that ignores local culture'],'D','For example, diabetes education that uses traditional foods can be more relevant and effective.',NIMHD),
  q(RED,'Why does community-based participatory research help reduce disparities?','Communities help design the studies',['It excludes community members from research','It uses only laboratory animal studies','It avoids collecting data'],'A','Partnership builds trust and makes findings more relevant to community needs.',NIMHD),
  q(RED,'According to the WHO, what does universal health coverage mean?','Needed care for all without financial hardship',['Every service is provided by the government','Only children and seniors are covered','Everyone pays the same price for insurance'],'C','UHC is a target of the Sustainable Development Goals and depends on strong primary health care.',WHO),
  q(RED,'Which program pairs patients with legal help to fix problems such as unsafe housing or denied benefits?','Medical-legal partnership',['Patient navigation for cancer','Telehealth','Mobile mammography'],'B','Legal problems are often social determinants of health; resolving them can improve health.',NIMHD),
  q(RED,'What is the role of a patient navigator?','Guiding patients through complex care',['Driving ambulances to the hospital','Writing prescriptions for patients','Performing surgery'],'D','Navigators help patients schedule tests, understand options and overcome barriers.',NIMHD)
 ],211)
};
